using System.Windows;
using System.Windows.Controls;
namespace WoWItemEditor;
internal sealed record QuestObjectiveRow(QuestObjectiveDraft Draft,string TargetName){public string TypeName=>QuestDefinitions.Types.GetValueOrDefault(Draft.Type)??"Unsupported";public int Amount=>Draft.Amount;public string Text=>Draft.Text;}
internal sealed record QuestRewardRow(QuestItemReward Draft,string Name){public int Count=>Draft.Count;}
internal sealed record QuestRepRow(QuestReputationReward Draft,string Name){public int Amount=>Draft.Amount;}
internal sealed class QuestForm : Grid
{
    private readonly CatalogResult catalog;internal TabControl Pages {get;}=new();
    private readonly Dictionary<string,TextBox> text=[];private readonly Dictionary<string,QuestReferenceField> references=[];
    private readonly ComboBox repeat=new(){ItemsSource=new[]{"Once","Repeatable","Daily","Weekly","Monthly"},SelectedIndex=0};
    private readonly CheckBox share=new(){Content="Shareable",IsChecked=true},raid=new(){Content="Allow progress in raid"},auto=new(){Content="Accept automatically"},allRaces=new(){Content="All races (includes custom server races)",IsChecked=true},allClasses=new(){Content="All classes",IsChecked=true};
    private readonly Dictionary<int,CheckBox> races=[],classes=[];private ulong loadedRaces=ulong.MaxValue;private bool racesTouched,levelTouched;
    private readonly DataGrid objectives=DesignerWindow.Table(("Objective","TypeName"),("Target","TargetName"),("Amount","Amount"),("Log text","Text"));
    private readonly DataGrid guaranteed=DesignerWindow.Table(("Guaranteed item","Name"),("Quantity","Count")),choices=DesignerWindow.Table(("Choose one item","Name"),("Quantity","Count")),reputation=DesignerWindow.Table(("Faction","Name"),("Reputation change","Amount"));
    private readonly List<QuestObjectiveRow> objectiveRows=[];private readonly List<QuestRewardRow> guaranteedRows=[],choiceRows=[];private readonly List<QuestRepRow> repRows=[];
    internal event Action? Changed;
    internal QuestForm(CatalogResult catalog,int defaultLevel=1){this.catalog=catalog;Children.Add(Pages);Page("Story & dialogue",Story());Page("Objectives",Objectives());Page("Rewards",Rewards());Page("Requirements & chain",Requirements());Page("NPC & presentation",Presentation());text["Level"].Text=Math.Clamp(defaultLevel,1,60).ToString();text["Level"].TextChanged+=(_,_)=>levelTouched=true;}
    internal void SuggestLevel(int level){if(levelTouched)return;text["Level"].Text=Math.Clamp(level,1,60).ToString();levelTouched=false;}
    private void Page(string name,UIElement element)=>Pages.Items.Add(new TabItem{Header=name,Content=element});
    private StackPanel Panel()=>new(){Margin=new Thickness(14)};
    private UIElement Scroll(StackPanel panel)=>new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
    private static void Label(Panel panel,string name,UIElement element){panel.Children.Add(DesignerWindow.Text(name,12));if(element is FrameworkElement f)f.Margin=new Thickness(0,5,0,14);panel.Children.Add(element);}
    private TextBox Field(Panel panel,string key,string label,string value="",bool multiline=false){var box=new TextBox{Text=value,AcceptsReturn=multiline,TextWrapping=multiline?TextWrapping.Wrap:TextWrapping.NoWrap,MinHeight=multiline?85:34};text[key]=box;Label(panel,label,box);box.TextChanged+=(_,_)=>Changed?.Invoke();return box;}
    private QuestReferenceField Reference(Panel panel,string key,string title,string kind){var field=new QuestReferenceField(kind,catalog);references[key]=field;Label(panel,title,field);field.Changed+=()=>Changed?.Invoke();return field;}
    private UIElement Story(){var p=Panel();var help=DesignerWindow.Text("Use $N for player name, $C for class, $R for race, $B for a new line. Example: Welcome, $N!$BWill you help me?",13);help.TextWrapping=TextWrapping.Wrap;p.Children.Add(help);Field(p,"Title","Quest title");Field(p,"Summary","Quest-log instructions");Field(p,"Description","NPC offer dialogue",multiline:true);Field(p,"CompletionLog","Quest-log text after objectives are complete");Field(p,"Incomplete","NPC dialogue while objectives are incomplete",multiline:true);Field(p,"RewardText","NPC completion / reward dialogue",multiline:true);Field(p,"AreaText","Area / event description (optional)");return Scroll(p);}
    private UIElement Objectives(){var root=new DockPanel{Margin=new Thickness(14)};var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);var help=DesignerWindow.Text("Add the objectives players must complete, in log order. No objectives creates a talk / turn-in quest. Collection uses existing item drops; configure missing loot through the item's drop editor. Object interactions must already award quest credit. Exploration uses an existing, unassigned area trigger. Escorts, scripted events and cinematics require server scripts.",12);help.TextWrapping=TextWrapping.Wrap;top.Children.Add(help);var actions=new WrapPanel();top.Children.Add(actions);DesignerWindow.Button("Add objective",actions).Click+=async(_,_)=>await EditObjective(false);DesignerWindow.Button("Edit selected",actions).Click+=async(_,_)=>await EditObjective(true);DesignerWindow.Button("Remove",actions).Click+=(_,_)=>{if(objectives.SelectedItem is QuestObjectiveRow row)objectiveRows.Remove(row);Refresh();};DesignerWindow.Button("Move up",actions).Click+=(_,_)=>Move(-1);DesignerWindow.Button("Move down",actions).Click+=(_,_)=>Move(1);root.Children.Add(objectives);return root;}
    private async Task EditObjective(bool edit){var old=edit?objectives.SelectedItem as QuestObjectiveRow:null;if(edit&&old is null)return;if(!edit&&objectiveRows.Count>=8){MessageBox.Show("Maximum 8 objectives.");return;}var dialog=new QuestObjectiveWindow(catalog,old?.Draft){Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true||dialog.Result is not {} result)return;var row=new QuestObjectiveRow(result,await TargetLabel(result));if(old is null)objectiveRows.Add(row);else objectiveRows[objectiveRows.IndexOf(old)]=row;Refresh();}
    private async Task<string> TargetLabel(QuestObjectiveDraft o)=>o.Type is 8 or 9?"No target required":await QuestReferences.Label(QuestObjectiveWindow.Kind(o.Type),o.Target,catalog);
    private void Move(int offset){if(objectives.SelectedItem is not QuestObjectiveRow row)return;int index=objectiveRows.IndexOf(row),next=index+offset;if(next<0||next>=objectiveRows.Count)return;objectiveRows.RemoveAt(index);objectiveRows.Insert(next,row);Refresh();objectives.SelectedItem=row;}
    private UIElement Rewards(){var p=Panel();Field(p,"XP","Base XP at quest level (0–100,000)","0");Field(p,"Gold","Gold reward (0–1,000; up to four decimal places)","0");var help=DesignerWindow.Text("Player level, server rates and level-cap conversion can change actual XP and gold. Guaranteed items are all awarded; choice rewards let the player pick one. Items are optional.",12);help.TextWrapping=TextWrapping.Wrap;p.Children.Add(help);RewardList(p,guaranteed,guaranteedRows,"Guaranteed items (maximum 4)",4);RewardList(p,choices,choiceRows,"Choose-one rewards (maximum 6)",6);Reference(p,"SourceItem","Item given on acceptance (optional)","Item");Field(p,"SourceCount","Starting-item quantity (1–20)","1");Reference(p,"SourceSpell","Spell cast on acceptance (optional; existing spell)","Spell");Reference(p,"RewardSpell","Spell cast on completion (optional; existing spell)","Spell");Label(p,"Reputation rewards (maximum 5)",reputation);reputation.Height=170;var actions=new WrapPanel();p.Children.Add(actions);DesignerWindow.Button("Add reputation",actions).Click+=async(_,_)=>{if(repRows.Count>=5)return;var picker=new QuestReferencePicker("Faction",catalog){Owner=Window.GetWindow(this)};if(picker.ShowDialog()!=true||picker.Selected is not {} selected)return;int? amount=QuestNumberWindow.Ask(Window.GetWindow(this),"Reputation change (-42,000 to 42,000)",250,-42000,42000);if(amount is null)return;repRows.Add(new(new(selected.Id,amount.Value),selected.Name));Refresh();await Task.CompletedTask;};DesignerWindow.Button("Change amount",actions).Click+=(_,_)=>{if(reputation.SelectedItem is not QuestRepRow row)return;int? amount=QuestNumberWindow.Ask(Window.GetWindow(this),"Reputation change",row.Amount,-42000,42000);if(amount is null)return;repRows[repRows.IndexOf(row)]=row with{Draft=row.Draft with{Amount=amount.Value}};Refresh();};DesignerWindow.Button("Remove reputation",actions).Click+=(_,_)=>{if(reputation.SelectedItem is QuestRepRow row)repRows.Remove(row);Refresh();};return Scroll(p);}
    private void RewardList(StackPanel p,DataGrid grid,List<QuestRewardRow> rows,string title,int limit){grid.Height=170;Label(p,title,grid);var actions=new WrapPanel();p.Children.Add(actions);DesignerWindow.Button("Add item",actions).Click+=(_,_)=>{if(rows.Count>=limit){MessageBox.Show($"Maximum {limit} items.");return;}var picker=new QuestReferencePicker("Item",catalog){Owner=Window.GetWindow(this)};if(picker.ShowDialog()!=true||picker.Selected is not {} selected)return;int? count=QuestNumberWindow.Ask(Window.GetWindow(this),"Item quantity (1–1,000)",1,1,1000);if(count is null)return;rows.Add(new(new(selected.Id,count.Value),selected.Name));Refresh();};DesignerWindow.Button("Change quantity",actions).Click+=(_,_)=>{if(grid.SelectedItem is not QuestRewardRow row)return;int? count=QuestNumberWindow.Ask(Window.GetWindow(this),"Item quantity",row.Count,1,1000);if(count is null)return;rows[rows.IndexOf(row)]=row with{Draft=row.Draft with{Count=count.Value}};Refresh();};DesignerWindow.Button("Remove item",actions).Click+=(_,_)=>{if(grid.SelectedItem is QuestRewardRow row)rows.Remove(row);Refresh();};}
    private UIElement Requirements(){var p=Panel();var note=DesignerWindow.Text("The ! marker depends on character level and eligibility. Trivial quests may require low-level quest tracking in WoW. Saved edits become active after a worldserver restart.",13);note.TextWrapping=TextWrapping.Wrap;p.Children.Add(note);Field(p,"Level","Quest level (1–60)","1");Field(p,"Minimum","Minimum character level (1–60)","1");Field(p,"Maximum","Maximum character level (0 = no maximum)","0");Field(p,"Time","Time limit in seconds (0 = untimed, maximum 86,400)","0");Field(p,"Group","Suggested group size (1–40)","1");Label(p,"Repeat schedule",repeat);foreach(var box in new[]{share,raid,auto}){p.Children.Add(box);box.Checked+=(_,_)=>Changed?.Invoke();box.Unchecked+=(_,_)=>Changed?.Invoke();}repeat.SelectionChanged+=(_,_)=>Changed?.Invoke();p.Children.Add(allRaces);var racePanel=new WrapPanel();p.Children.Add(racePanel);foreach(var (id,name) in new Dictionary<int,string>{{1,"Human"},{2,"Orc"},{3,"Dwarf"},{4,"Night elf"},{5,"Undead"},{6,"Tauren"},{7,"Gnome"},{8,"Troll"}}){var box=new CheckBox{Content=name,IsChecked=true,Margin=new Thickness(8)};races[id]=box;racePanel.Children.Add(box);box.Checked+=(_,_)=>{racesTouched=true;Changed?.Invoke();};box.Unchecked+=(_,_)=>{racesTouched=true;Changed?.Invoke();};}allRaces.Checked+=(_,_)=>{racePanel.IsEnabled=false;Changed?.Invoke();};allRaces.Unchecked+=(_,_)=>{racePanel.IsEnabled=true;racesTouched=true;Changed?.Invoke();};racePanel.IsEnabled=false;p.Children.Add(allClasses);var classPanel=new WrapPanel();p.Children.Add(classPanel);foreach(var (id,name) in new Dictionary<int,string>{{1,"Warrior"},{2,"Paladin"},{3,"Hunter"},{4,"Rogue"},{5,"Priest"},{7,"Shaman"},{8,"Mage"},{9,"Warlock"},{11,"Druid"}}){var box=new CheckBox{Content=name,IsChecked=true,Margin=new Thickness(8)};classes[id]=box;classPanel.Children.Add(box);box.Checked+=(_,_)=>Changed?.Invoke();box.Unchecked+=(_,_)=>Changed?.Invoke();}allClasses.Checked+=(_,_)=>{classPanel.IsEnabled=false;Changed?.Invoke();};allClasses.Unchecked+=(_,_)=>{classPanel.IsEnabled=true;Changed?.Invoke();};classPanel.IsEnabled=false;Reference(p,"Previous","Must have completed quest", "Quest");Reference(p,"Next","Next quest in chain / offer on completion","Quest");Field(p,"Exclusive","Exclusive group ID (0 = none; matching positive groups are alternatives)","0");Reference(p,"Skill","Required profession / skill","Skill");Field(p,"SkillPoints","Required skill points (0–450)","0");Reference(p,"RepFaction","Required minimum reputation faction","Faction");Field(p,"RepValue","Required reputation standing (-42,000 to 42,000)","0");return Scroll(p);}
    private UIElement Presentation(){var p=Panel();Reference(p,"EndNpc","Turn-in NPC (None = the copied quest giver)","Questgiver");Reference(p,"Category","Quest type / category (None = normal)","Category");Reference(p,"Zone","Quest-log zone (None = placement zone on create; current zone on edit)","Zone");Reference(p,"AcceptEmote","NPC emote on quest offer","Emote");Reference(p,"CompleteEmote","NPC emote on completion","Emote");Reference(p,"IncompleteEmote","NPC emote while incomplete","Emote");return Scroll(p);}
    private void Refresh(){objectives.ItemsSource=objectiveRows.ToArray();guaranteed.ItemsSource=guaranteedRows.ToArray();choices.ItemsSource=choiceRows.ToArray();reputation.ItemsSource=repRows.ToArray();Changed?.Invoke();}
    private int Number(string key)=>int.TryParse(text[key].Text,out int value)?value:throw new InvalidOperationException($"Enter a whole number for {key}.");
    internal QuestDraft Draft(string npc,bool ground=true){if(!decimal.TryParse(text["Gold"].Text,out decimal money)||money<0||money>1000||decimal.Round(money,4)!=money)throw new InvalidOperationException("Gold must be 0–1,000 with at most four decimal places.");ulong raceMask=allRaces.IsChecked==true?ulong.MaxValue:!racesTouched?loadedRaces:races.Where(p=>p.Value.IsChecked==true).Aggregate(0UL,(mask,p)=>mask|(1UL<<(p.Key-1)));uint classMask=allClasses.IsChecked==true?0:classes.Where(p=>p.Value.IsChecked==true).Aggregate(0u,(mask,p)=>mask|(1u<<(p.Key-1)));if(allClasses.IsChecked!=true&&classMask==0)throw new InvalidOperationException("Select at least one class.");return new(npc,text["Title"].Text,text["Summary"].Text,text["Description"].Text,text["RewardText"].Text,Number("Level"),Number("Minimum"),guaranteedRows.FirstOrDefault()?.Draft.Item??0,guaranteedRows.FirstOrDefault()?.Draft.Count??0,ground,Number("XP"),(int)(money*10000)){Options=new(){Objectives=objectiveRows.Select(r=>r.Draft).ToList(),Guaranteed=guaranteedRows.Select(r=>r.Draft).ToList(),Choices=choiceRows.Select(r=>r.Draft).ToList(),Reputation=repRows.Select(r=>r.Draft).ToList(),CompletionLog=text["CompletionLog"].Text,IncompleteText=text["Incomplete"].Text,AreaText=text["AreaText"].Text,MaxLevel=Number("Maximum"),TimeSeconds=Number("Time"),SuggestedPlayers=Number("Group"),Repeat=repeat.SelectedItem as string??"Once",Shareable=share.IsChecked==true,RaidAllowed=raid.IsChecked==true,AutoAccept=auto.IsChecked==true,Races=raceMask,Classes=classMask,PreviousQuest=references["Previous"].Id,NextQuest=references["Next"].Id,ExclusiveGroup=Number("Exclusive"),RequiredSkill=references["Skill"].Id,RequiredSkillPoints=Number("SkillPoints"),RequiredRepFaction=references["RepFaction"].Id,RequiredRepValue=Number("RepValue"),SourceItem=references["SourceItem"].Id,SourceCount=Number("SourceCount"),SourceSpell=references["SourceSpell"].Id,RewardSpell=references["RewardSpell"].Id,EndNpc=references["EndNpc"].Id,QuestInfo=references["Category"].Id,QuestSort=references["Zone"].Id,AcceptEmote=references["AcceptEmote"].Id,CompleteEmote=references["CompleteEmote"].Id,IncompleteEmote=references["IncompleteEmote"].Id}};}
    internal async Task Bind(QuestDraft draft){var o=draft.Options;void Set(string key,object value)=>text[key].Text=Convert.ToString(value,System.Globalization.CultureInfo.CurrentCulture)??"";Set("Title",draft.Title);Set("Summary",draft.Summary);Set("Description",draft.Description);Set("RewardText",draft.RewardText);Set("CompletionLog",o.CompletionLog);Set("Incomplete",o.IncompleteText);Set("AreaText",o.AreaText);Set("Level",draft.Level);Set("Minimum",draft.MinLevel);Set("Maximum",o.MaxLevel);Set("Time",o.TimeSeconds);Set("Group",o.SuggestedPlayers);Set("XP",draft.Experience);Set("Gold",draft.MoneyCopper/10000m);Set("SourceCount",o.SourceCount);Set("Exclusive",o.ExclusiveGroup);Set("SkillPoints",o.RequiredSkillPoints);Set("RepValue",o.RequiredRepValue);repeat.SelectedItem=o.Repeat;share.IsChecked=o.Shareable;raid.IsChecked=o.RaidAllowed;auto.IsChecked=o.AutoAccept;allRaces.IsChecked=o.Races==ulong.MaxValue;foreach(var (id,box) in races)box.IsChecked=(o.Races&(1UL<<(id-1)))!=0;loadedRaces=o.Races;racesTouched=false;allClasses.IsChecked=o.Classes==0;foreach(var (id,box) in classes)box.IsChecked=o.Classes==0||(o.Classes&(1u<<(id-1)))!=0;
        foreach(var (key,id) in new Dictionary<string,int>{{"Previous",o.PreviousQuest},{"Next",o.NextQuest},{"Skill",o.RequiredSkill},{"RepFaction",o.RequiredRepFaction},{"SourceItem",o.SourceItem},{"SourceSpell",o.SourceSpell},{"RewardSpell",o.RewardSpell},{"EndNpc",o.EndNpc},{"Category",o.QuestInfo},{"Zone",o.QuestSort},{"AcceptEmote",o.AcceptEmote},{"CompleteEmote",o.CompleteEmote},{"IncompleteEmote",o.IncompleteEmote}})await references[key].Set(id);
        objectiveRows.Clear();foreach(var objective in o.Objectives)objectiveRows.Add(new(objective,await TargetLabel(objective)));guaranteedRows.Clear();choiceRows.Clear();foreach(var reward in QuestDefinitions.Guaranteed(draft))guaranteedRows.Add(new(reward,await QuestReferences.Label("Item",reward.Item,catalog)));foreach(var reward in o.Choices)choiceRows.Add(new(reward,await QuestReferences.Label("Item",reward.Item,catalog)));repRows.Clear();foreach(var reward in o.Reputation)repRows.Add(new(reward,await QuestReferences.Label("Faction",reward.Faction,catalog)));Refresh();}
    internal string Review(QuestDraft draft)=>QuestReview.Describe(draft,catalog);
}
internal sealed class QuestNumberWindow : Window
{
    internal static int? Ask(Window owner,string title,int initial,int min,int max){var window=new Window{Title=title,Width=460,Height=190,Owner=owner,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=TooltipView.Brush("#232428")};var panel=new StackPanel{Margin=new Thickness(20)};window.Content=panel;var input=new TextBox{Text=initial.ToString()};panel.Children.Add(input);var error=DesignerWindow.Text("",12);panel.Children.Add(error);int? result=null;DesignerWindow.Button("Use value",panel).Click+=(_,_)=>{if(!int.TryParse(input.Text,out int value)||value<min||value>max){error.Text=$"Use a value from {min} to {max}.";return;}result=value;window.DialogResult=true;};window.ShowDialog();return result;}
}
internal sealed class QuestObjectiveWindow : Window
{
    internal QuestObjectiveDraft? Result {get;private set;}
    internal static string Kind(int type)=>type switch{0 or 3=>"Creature",1=>"Item",2=>"Object",5=>"Spell",6 or 7=>"Faction",10=>"Trigger",_=>"Creature"};
    internal QuestObjectiveWindow(CatalogResult catalog,QuestObjectiveDraft? current){Title="Quest objective";Width=740;Height=480;MinWidth=650;MinHeight=450;Background=TooltipView.Brush("#232428");WindowStartupLocation=WindowStartupLocation.CenterOwner;var panel=new StackPanel{Margin=new Thickness(20)};Content=panel;var types=new ComboBox{ItemsSource=QuestDefinitions.Types.Select(p=>new FilterChoice(p.Key,p.Value)).ToArray()};var target=new QuestReferenceField(Kind(current?.Type??0),catalog);var amount=new TextBox{Text=(current?.Amount??1).ToString()};var description=new TextBox{Text=current?.Text??""};var error=DesignerWindow.Text("",12);foreach(var (label,control) in new (string,UIElement)[]{("Objective type",types),("Target (not required for money or player kills)",target),("Amount / standing / copper (learning and exploration: 1)",amount),("Custom quest-log objective text (optional)",description)}){panel.Children.Add(DesignerWindow.Text(label,12));if(control is FrameworkElement f)f.Margin=new Thickness(0,4,0,14);panel.Children.Add(control);}panel.Children.Add(error);types.SelectionChanged+=async(_,_)=>{int type=(types.SelectedItem as FilterChoice)?.Id??0;target.Kind=Kind(type);target.IsEnabled=type is not (8 or 9);await target.Set(0);};types.SelectedItem=types.Items.Cast<FilterChoice>().First(c=>c.Id==(current?.Type??0));Loaded+=async(_,_)=>{if(current is not null)await target.Set(current.Target);};DesignerWindow.Button("Use objective",panel).Click+=(_,_)=>{try{int type=((FilterChoice)types.SelectedItem).Id;if(!int.TryParse(amount.Text,out int count))throw new InvalidOperationException("Enter a whole-number amount.");var objective=new QuestObjectiveDraft(current?.Id??0,type,type is 8 or 9?0:target.Id,count,description.Text);QuestDefinitions.Validate(new("NPC","Quest","Instructions","Offer","Reward",1,1,0,0,true){Options=new(){Objectives=[objective]}});Result=objective;DialogResult=true;}catch(Exception ex){error.Text=ex.Message;}};}
}
internal static class QuestReview
{
    internal static string Describe(QuestDraft draft,CatalogResult catalog){var o=draft.Options;string Item(QuestItemReward r)=>(catalog.Items.FirstOrDefault(i=>i.Id==r.Item)?.Name??$"Item {r.Item}")+" × "+r.Count;return $"{draft.Title}\nNPC: {draft.NpcName}\nLevel {draft.Level}; minimum {draft.MinLevel}; maximum {(o.MaxLevel==0?"none":o.MaxLevel)}\n{o.Repeat}; time limit {o.TimeSeconds} seconds; group {o.SuggestedPlayers}\n\nOFFER\n{draft.Description}\n\nLOG\n{draft.Summary}\n\nOBJECTIVES\n"+string.Join("\n",o.Objectives.Select(r=>$"{QuestDefinitions.Types[r.Type]} · target {r.Target} · amount {r.Amount} · {r.Text}"))+$"\n\nINCOMPLETE\n{o.IncompleteText}\n\nCOMPLETION\n{o.CompletionLog}\n{draft.RewardText}\n\nREWARDS\nBase XP {draft.Experience}; gold {draft.MoneyCopper/10000m}\nGuaranteed: "+string.Join(", ",QuestDefinitions.Guaranteed(draft).Select(Item))+"\nChoose one: "+string.Join(", ",o.Choices.Select(Item))+"\nReputation: "+string.Join(", ",o.Reputation.Select(r=>$"Faction {r.Faction}: {r.Amount:+0;-0;0}"))+$"\nStarting item {o.SourceItem} × {o.SourceCount}; start spell {o.SourceSpell}; reward spell {o.RewardSpell}\n\nREQUIREMENTS\nPrevious quest {o.PreviousQuest}; next {o.NextQuest}; exclusive group {o.ExclusiveGroup}\nRaces: {(o.Races==ulong.MaxValue?"All":o.Races)}; classes: {(o.Classes==0?"All":o.Classes)}\nSkill {o.RequiredSkill}: {o.RequiredSkillPoints}; faction {o.RequiredRepFaction}: {o.RequiredRepValue}\nTurn-in: {(o.EndNpc==0?"Copied quest giver":o.EndNpc)}\nCategory {o.QuestInfo}; zone {o.QuestSort}; emotes {o.AcceptEmote}/{o.IncompleteEmote}/{o.CompleteEmote}\nShareable {o.Shareable}; raid {o.RaidAllowed}; auto-accept {o.AutoAccept}\n\nRestart the worldserver before testing saved changes. No character records are edited.";}
}
